    })
  },

  push(ctx, router, uri, type) {
    var enterType = type || 'fromRight'
    var exitType = getExitType(enterType)
    pendingEnterType = enterType
    runFrames(ctx, exitType, true, function () {
      router.push({ uri: uri })
    })
  },

  replace(ctx, router, uri, type) {
    var enterType = type || 'fromRight'
    var exitType = getExitType(enterType)
    pendingEnterType = enterType
    runFrames(ctx, exitType, true, function () {
      if (router.replace) {
        router.replace({ uri: uri })
      } else {
        router.push({ uri: uri })
      }
    })
  },

  clear: clearMotion
}
