        <div class="chart-bars">
          <div class="bar-wrapper" for="{{ hourlyData }}">
            <div class="bar" style="height: {{ $item.barHeight }}px; margin-bottom: {{ $item.barBottom }}px;"></div>
          </div>
        </div>
        <div class="chart-divider"></div>
        <div class="chart-stats">
          <text class="stat-val stat-max-val">{{ dailyMax }}</text>
          <text class="stat-val stat-min-val">{{ dailyMin }}</text>
        </div>
      </div>
      <div class="labels-row">
        <text class="hour-label" for="{{ hourlyData }}">{{ $item.label }}</text>
      </div>
    </div>
    <text class="hr-label" static="true">当前心率</text>
    <div class="hr-icon-wrapper">
      <image class="hr-icon" src="/common/heart.png"></image>
    </div>
    <text class="hr-number">{{ currentHR }}</text>
    <text class="hr-unit" static="true">次/分</text>
  </div>
