<script>
import router from '@system.router'
import pageMotion from '../../common/page_motion'
import watchData from '../../common/watch_data'

var CHART_HEIGHT = 160
var CHART_MIN_BPM = 40
var CHART_MAX_BPM = 100

function buildHourlyChart(hourlyData) {
  if (!hourlyData || hourlyData.length === 0) {
    return []
  }
  var scale = CHART_HEIGHT / (CHART_MAX_BPM - CHART_MIN_BPM)
  var result = []
  for (var i = 0; i < hourlyData.length; i++) {
    var d = hourlyData[i]
    result.push({
      label: d.label,
      barHeight: Math.round((d.max - d.min) * scale),
      barBottom: Math.round((d.min - CHART_MIN_BPM) * scale)
    })
  }
  return result
}

function calcHourlyRange(hourlyData) {
  if (!hourlyData || hourlyData.length === 0) {
    return { min: 0, max: 0 }
  }
  var min = hourlyData[0].min
  var max = hourlyData[0].max
  for (var i = 1; i < hourlyData.length; i++) {
    if (hourlyData[i].min < min) min = hourlyData[i].min
    if (hourlyData[i].max > max) max = hourlyData[i].max
  }
  return { min: min, max: max }
}

export default {
  private: {
    hourlyData: [],
    dailyMin: 0,
    dailyMax: 0,
    currentHR: 0,
    touchStartX: 0,
    pageOpacity: 1,
    pageOffset: 0,
    motionTimer: null,
    heartRateTimer: null
  },

  onInit() {
    this.$page.setTitleBar({ text: '心率' })
  },

  onShow() {
    this.loadFromWatchData()
    this.startHeartRateTimer()
    pageMotion.enter(this)
  },

  onHide() {
    pageMotion.clear(this)
    this.stopHeartRateTimer()
    this.releaseChartData()
  },

  onDestroy() {
    pageMotion.clear(this)
    this.stopHeartRateTimer()
    this.releaseChartData()
  },

  loadFromWatchData() {
    var self = this
    this.applyCurrentHeartRate(watchData.getSnapshot())
    watchData.loadHourlyHeartRate(function (hourlyData) {
      self.applyHourlyHeartRate(hourlyData)
    })
  },

  startHeartRateTimer() {
    var self = this
    this.stopHeartRateTimer()
    this.heartRateTimer = setInterval(function () {
      self.applyCurrentHeartRate(watchData.tickHeartRate())
    }, 1000)
  },

  stopHeartRateTimer() {
    clearInterval(this.heartRateTimer)
    this.heartRateTimer = null
  },

  applyCurrentHeartRate(snapshot) {
    this.currentHR = snapshot.currentHeartRate
  },

  applyHourlyHeartRate(hourlyData) {
    this.hourlyData = buildHourlyChart(hourlyData)
    var range = calcHourlyRange(hourlyData)
    this.dailyMin = range.min
    this.dailyMax = range.max
  },

  releaseChartData() {
    this.hourlyData = []
  },

  onTouchStart(e) {
    this.touchStartX = e.touches[0].pageX
  },

  onTouchEnd(e) {
    var touchEndX = e.changedTouches[0].pageX
    var diffX = touchEndX - this.touchStartX

    // 右滑动阈值设为30px
    if (diffX > 30) {
      pageMotion.back(this, router)
    }
  }
}
</script>

