<script>
import router from '@system.router'
import watchData from '../../common/watch_data'
import pageMotion from '../../common/page_motion'

export default {
  private: {
    todayStepsText: '0',
    avgStepsText: '0',
    bestStepsText: '0',
    bestDayText: '--',
    avgHeartText: '--',
    totalCaloriesText: '0',
    goalText: '0%',
    stepBars: [],
    records: [],
    pageVisible: false,
    pageOpacity: 1,
    pageOffset: 0,
    motionTimer: null
  },

  onInit() {
    this.$page.setTitleBar({ text: '7日趋势' })
  },

  onShow() {
    this.pageVisible = true
    pageMotion.enter(this)
    this.loadHistory()
  },

  onHide() {
    this.pageVisible = false
    pageMotion.clear(this)
    this.releaseHistoryData()
  },

  onDestroy() {
    this.pageVisible = false
    pageMotion.clear(this)
    this.releaseHistoryData()
  },

  loadHistory() {
    // Data is refreshed in onShow so the page always reflects the latest saved day.
    watchData.getHistorySummary((summary) => {
      if (!this.pageVisible) {
        return
      }
      this.todayStepsText = summary.todayStepsText
      this.avgStepsText = summary.avgStepsText
      this.bestStepsText = summary.bestStepsText
      this.bestDayText = summary.bestDayText
      this.avgHeartText = summary.avgHeartText
      this.totalCaloriesText = summary.totalCaloriesText
      this.goalText = summary.goalText
      this.stepBars = summary.stepBars
      this.records = summary.records
    })
  },

  releaseHistoryData() {
    // Free chart/list references while the page is cached in the navigation stack.
    this.stepBars = []
    this.records = []
  },

  goBack() {
    pageMotion.back(this, router)
  },

  handleSwipe(e) {
    if (e.direction === 'down' || e.direction === 'right') {
      pageMotion.back(this, router)
    }
  }
}
</script>

