<script>
import router from '@system.router'
import workoutManager from '../../common/workout_manager'
import pageMotion from '../../common/page_motion'

export default {
  private: {
    touchStartX: 0,
    totalCount: '0',
    totalSteps: '0',
    emptyVisible: true,
    records: [],
    pageVisible: false,
    pageOpacity: 1,
    pageOffset: 0,
    motionTimer: null
  },

  onShow() {
    this.pageVisible = true
    pageMotion.enter(this)
    this.loadRecords()
  },

  onHide() {
    this.pageVisible = false
    pageMotion.clear(this)
    this.releaseRecords()
  },

  onDestroy() {
    this.pageVisible = false
    pageMotion.clear(this)
    this.releaseRecords()
  },

  loadRecords() {
    var self = this
    workoutManager.getRecords(function (records) {
      if (!self.pageVisible) {
        return
      }
      var totalSteps = 0
      for (var i = 0; i < records.length; i++) {
        totalSteps += records[i].steps
        records[i].syncText = records[i].synced ? '已同步' : '待同步'
        records[i].distanceSourceText = records[i].distanceSource === 'gps' ? 'GPS 距离' : '步幅估算'
      }
      self.records = records
      self.totalCount = records.length.toString()
      self.totalSteps = totalSteps.toString()
      self.emptyVisible = records.length === 0
    })
  },

  releaseRecords() {
    // Drop list references when hidden; storage remains the source of truth.
    this.records = []
  },

  goBack() {
    pageMotion.back(this, router)
  },

  onTouchStart(e) {
    if (e.touches && e.touches[0]) {
      this.touchStartX = e.touches[0].pageX
    }
  },

  onTouchEnd(e) {
    if (e.changedTouches && e.changedTouches[0] && e.changedTouches[0].pageX - this.touchStartX > 30) {
      pageMotion.back(this, router)
    }
  }
}
</script>

