    <div class="slider-card">
      <div class="slider-label-row">
        <text class="slider-label" static="true">手动亮度</text>
        <text class="slider-state">{{ manualStateText }}</text>
      </div>
      <slider class="brightness-slider"
        min="0"
        max="255"
        step="1"
        value="{{ brightnessValue }}"
        enabled="{{ manualEnabled }}"
        @change="onBrightnessChange">
      </slider>
      <div class="slider-scale">
        <text class="scale-text" static="true">暗</text>
        <text class="scale-text center" static="true">中</text>
        <text class="scale-text right" static="true">亮</text>
      </div>
    </div>

    <div class="setting-card" @click="toggleAutoBrightness">
      <div class="setting-copy">
        <text class="setting-title" static="true">自动亮度</text>
        <text class="setting-sub" static="true">根据场景模拟调节</text>
      </div>
      <text class="switch-text" style="color: {{ autoColor }}">{{ autoText }}</text>
    </div>

    <div class="setting-card" @click="toggleRaiseWake">
      <div class="setting-copy">
        <text class="setting-title" static="true">抬腕亮屏</text>
        <text class="setting-sub" static="true">息屏后可模拟唤醒</text>
      </div>
      <text class="switch-text" style="color: {{ raiseColor }}">{{ raiseText }}</text>
    </div>

    <div class="setting-card" @click="toggleLowPower">
      <div class="setting-copy">
        <text class="setting-title" static="true">低功耗模式</text>
        <text class="setting-sub" static="true">暗屏/息屏/降刷新率</text>
      </div>
      <text class="switch-text" style="color: {{ lowPowerColor }}">{{ lowPowerText }}</text>
    </div>
