      <text class="status-label">通知震动</text>
      <text class="status-value" style="color: {{ statusColor }}">{{ statusText }}</text>
      <text class="status-sub">强度：{{ vibrationLevelText }}</text>
    </div>

    <div class="setting-card" @click="toggleVibration">
      <div class="setting-copy">
        <text class="setting-title">通知提醒</text>
        <text class="setting-sub">来电/短信/App 通知</text>
      </div>
      <text class="switch-text" style="color: {{ statusColor }}">{{ statusText }}</text>
    </div>

    <div class="level-row">
      <text class="level-button" style="background-color: {{ lightBg }}; color: {{ lightText }};" @click="setLight">轻</text>
      <text class="level-button" style="background-color: {{ mediumBg }}; color: {{ mediumText }};" @click="setMedium">中</text>
      <text class="level-button" style="background-color: {{ strongBg }}; color: {{ strongText }};" @click="setStrong">强</text>
    </div>

    <div class="test-card" @click="testVibration">
      <text class="test-title">测试震动</text>
      <text class="test-sub">{{ testText }}</text>
      <div class="pulse-dot" style="background-color: {{ pulseColor }}"></div>
    </div>
  </div>
</template>

<script>
import router from '@system.router'
import vibrator from '@system.vibrator'
import deviceSettings from '../../../common/device_settings'
import pageMotion from '../../../common/page_motion'

export default {
  private: {
    touchStartX: 0,
    vibrationEnabled: true,
    vibrationLevel: 'medium',
    vibrationLevelText: '中',
    statusText: '开',
    statusColor: '#30D158',
    lightBg: '#1C1C1E',
    mediumBg: '#FF9F0A',
    strongBg: '#1C1C1E',
    lightText: '#8E8E93',
    mediumText: '#000000',
    strongText: '#8E8E93',
    testText: '点击后模拟提醒震动',
    pulseColor: '#2C2C2E',
    pageOpacity: 1,
    pageOffset: 0,
    motionTimer: null
  },

  onInit() {
    this.$page.setTitleBar({ text: '震动' })
    this.loadSettings()
  },

  onShow() {
    pageMotion.enter(this)
    this.loadSettings()
  },

  loadSettings() {
    var self = this
    deviceSettings.load(function (settings) {
      self.vibrationEnabled = settings.vibrationEnabled
      self.vibrationLevel = settings.vibrationLevel
      self.refreshView()
    })
  },

  refreshView() {
    this.statusText = this.vibrationEnabled ? '开' : '关'
    this.statusColor = this.vibrationEnabled ? '#30D158' : '#8E8E93'
    this.vibrationLevelText = deviceSettings.getVibrationText(this.vibrationLevel)

    this.lightBg = this.vibrationLevel === 'light' ? '#FF9F0A' : '#1C1C1E'
    this.mediumBg = this.vibrationLevel === 'medium' ? '#FF9F0A' : '#1C1C1E'
    this.strongBg = this.vibrationLevel === 'strong' ? '#FF9F0A' : '#1C1C1E'
    this.lightText = this.vibrationLevel === 'light' ? '#000000' : '#8E8E93'
    this.mediumText = this.vibrationLevel === 'medium' ? '#000000' : '#8E8E93'
    this.strongText = this.vibrationLevel === 'strong' ? '#000000' : '#8E8E93'
  },

  toggleVibration() {
    this.vibrationEnabled = !this.vibrationEnabled
    this.refreshView()
    deviceSettings.update('vibrationEnabled', this.vibrationEnabled)
  },

  setLevel(level) {
    this.vibrationLevel = level
    this.refreshView()
    deviceSettings.update('vibrationLevel', level)
  },

  setLight() {
    this.setLevel('light')
  },

  setMedium() {
    this.setLevel('medium')
  },

  setStrong() {
    this.setLevel('strong')
  },

  testVibration() {
    var self = this
    if (!this.vibrationEnabled) {
      this.testText = '震动已关闭'
      this.pulseColor = '#8E8E93'
      return
    }

    this.testText = '正在测试：' + this.vibrationLevelText
    this.pulseColor = '#FF9F0A'
    try {
      if (vibrator && vibrator.vibrate) {
        vibrator.vibrate({
          mode: this.vibrationLevel === 'strong' ? 'long' : 'short',
          fail: function () {
            console.log('vibrator unavailable, use visual pulse')
          }
        })
      }
    } catch (e) {
      console.log('vibrator API unavailable, use visual pulse')
    }

    clearTimeout(this.testTimer)
    this.testTimer = setTimeout(function () {
      self.testText = '点击后模拟提醒震动'
      self.pulseColor = '#2C2C2E'
    }, 900)
  },

  onDestroy() {
    pageMotion.clear(this)
    clearTimeout(this.testTimer)
  },

  onHide() {
    pageMotion.clear(this)
  },

  onTouchStart(e) {
    this.touchStartX = e.touches[0].pageX
  },

  onTouchEnd(e) {
    var touchEndX = e.changedTouches[0].pageX
    if (touchEndX - this.touchStartX > 30) {
      pageMotion.back(this, router)
    }
  }
}
</script>

