    return 0
  }
  var percent = Math.round((value / goal) * 100)
  if (percent < 0) {
    return 0
  }
  if (percent > 100) {
    return 100
  }
  return percent
}

function calcGoalPercent() {
  // Three sport metrics share the same weight: steps, calories, stand hours.
  var stepsPercent = clampPercent(state.steps, state.stepsGoal)
  var caloriesPercent = clampPercent(state.calories, state.caloriesGoal)
  var standPercent = clampPercent(state.standHours, state.standGoal)
  return Math.round((stepsPercent + caloriesPercent + standPercent) / 3)
}

function calcHeartBarHeight(value) {
  var safeValue = Math.max(60, Math.min(100, value))
  return Math.round(((safeValue - 60) / 40) * 36) + 4
}

function makeNextHeartRate(lastRate) {
  // Simulate a small live heart-rate movement until a real sensor/database source is connected.
  var change = Math.floor(Math.random() * 21) - 10
  return Math.max(60, Math.min(100, lastRate + change))
}

function formatNumber(value) {
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',')
}

function pad2(value) {
  return value < 10 ? '0' + value : '' + value
}

function formatDate(date) {
