}

function parseStorageValue(data) {
  // Different openvela simulator versions may return value/data directly or inside an object.
  if (data && data.value !== undefined) {
    return data.value
  }
  if (data && data.data !== undefined) {
    return data.data
  }
  if (typeof data === 'string') {
    return data
  }
  return ''
}

function safeStorageSet(key, value) {
  // Simulator storage may be missing or incomplete; memory fallback keeps demo features running.
  memoryStorage[key] = value
  try {
    if (storage && storage.set) {
      storage.set({
        key: key,
        value: value,
        fail: function () {
          console.log('storage set failed, use memory fallback: ' + key)
        }
      })
    }
  } catch (e) {
    console.log('storage set unavailable, use memory fallback: ' + key)
  }
}

function safeStorageGet(key, success, fail) {
  // Prefer the latest in-memory write to avoid reading stale storage right after navigation.
  if (memoryStorage[key] !== undefined) {
    success({ value: memoryStorage[key] })
    return
  }

  try {
    if (storage && storage.get) {
      storage.get({
        key: key,
        success: success,
        fail: function () {
          if (memoryStorage[key] !== undefined) {
            success({ value: memoryStorage[key] })
          } else if (fail) {
            fail()
          }
        }
      })
      return
    }
  } catch (e) {
    console.log('storage get unavailable, use memory fallback: ' + key)
  }

  if (memoryStorage[key] !== undefined) {
    success({ value: memoryStorage[key] })
  } else if (fail) {
    fail()
  }
}

function parseHistoryList(data) {
  // Storage keeps JSON text; invalid or empty data falls back to demo history.
  var raw = parseStorageValue(data)
  if (!raw) {
    return []
  }
  try {
    var parsed = JSON.parse(raw)
    if (Array.isArray(parsed) && parsed.length) {
      return parsed
    }
  } catch (e) {
    console.log('health history parse failed, recreate demo data')
  }
  return []
}

